function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 1 || v > 2 ** 30 || (v & (v - 1)) !== 0) return 'Each value must be a power of two from 1 to 2^30.';
  }
  if (!Number.isInteger(target) || target < 1 || target >= 2 ** 31) return 'target is from 1 to 2^31 - 1.';
  return null;
}

