function minOperations(nums, target) {
  const count = new Array(32).fill(0);
  let total = 0;
  for (const num of nums) {
    count[31 - Math.clz32(num)]++;
    total += num;
  }
  if (total < target) {
    return -1;
  }

  let operations = 0;
  for (let bit = 0; bit < 31; bit++) {
    if ((target >> bit) & 1) {
      if (count[bit] > 0) {
        count[bit]--;
      } else {
        let higher = bit + 1;
        while (count[higher] === 0) {
          higher++;
        }
        operations += higher - bit;
        count[higher]--;
        for (let b = bit; b < higher; b++) {
          count[b]++;
        }
      }
    }
    count[bit + 1] += Math.floor(count[bit] / 2);
  }
  return operations;
}

