function minOperations(nums, target) {
  // Largest-first greedy on the actual pieces: drop, use or split the biggest one.
  const pieces = [...nums].sort((a, b) => a - b);
  let rest = pieces.reduce((s, v) => s + v, 0);
  if (rest < target) return -1;
  let ops = 0;
  let need = target;
  while (need > 0) {
    const a = pieces.pop();
    rest -= a;
    if (rest >= need) continue;
    if (a <= need) { need -= a; continue; }
    pieces.push(a / 2, a / 2);
    rest += a;
    ops++;
  }
  return ops;
}

