function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 600 + Math.floor(rand() * 401) : 1 + Math.floor(rand() * 6);
  // Leaving out the small powers forces splits, so the answers are not all 0.
  const minExp = Math.floor(rand() * (large ? 26 : 4));
  const maxExp = minExp + Math.floor(rand() * ((large ? 31 : 6) - minExp));
  const nums = Array.from({ length: n }, () => 2 ** (minExp + Math.floor(rand() * (maxExp - minExp + 1))));
  const total = nums.reduce((s, v) => s + v, 0);
  const limit = Math.min(2 ** 31 - 1, Math.floor(total * 1.15) + 2);
  const target = 1 + Math.floor(rand() * limit);
  return [nums, target];
}
